// Normalize a submitted referral from a form / landing page / CRM webhook.
const b = $json.body || {};
const q = $json.query || {};
const nests = [b, b.data, b.referral, b.fields, q].filter(Boolean);
const pick = (...keys) => { for (const src of nests) { for (const k of keys) { const v = src && src[k]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } } return ''; };
const e164 = raw => { let p = String(raw || '').trim(); const d = p.replace(/[^0-9]/g, ''); if (d.length === 10) return '+1' + d; if (d.length === 11 && d.startsWith('1')) return '+' + d; return p && !p.startsWith('+') ? (d ? '+' + d : '') : p; };
const referrer_name = pick('referrer_name','referrerName','from_name','your_name','referrer');
const referrer_phone = e164(pick('referrer_phone','referrerPhone','your_phone','from_phone'));
const referred_name = pick('referred_name','referredName','friend_name','name','referred_person','their_name');
const referred_phone = e164(pick('referred_phone','referredPhone','friend_phone','phone','their_phone'));
const referred_email = pick('referred_email','referredEmail','friend_email','email','their_email');
const service = pick('service_needed','service','service_type','need','reason','interest');
const relationship = pick('relationship','relation','how_know');
const notes = pick('notes','message','comments','details','description');
const wants_contact = /yes|true|asap|now|call/i.test(pick('wants_contact','contact_me','call_me') || '');
const source = pick('source') || q.source || 'Referral Form';
const referral_id = `${$now.toMillis()}-${referred_phone.replace(/[^0-9]/g,'').slice(-4)}`;
return [{ json: { referral_id, referrer_name, referrer_phone, referred_name, referred_phone, referred_email, service, relationship, notes, wants_contact, source, received_at: $now.toISO() } }];

