try { p = typeof ai === 'string' ? JSON.parse(ai) : ai; }
catch (e) { p = { summary:'New referral submitted', high_value:false, urgent:false, wants_contact:false, suggested_owner_message:'' }; }
const n = $('Normalize Referral').item.json;
const high_value = !!p.high_value;
const urgent = !!p.urgent;
const wants_contact = !!p.wants_contact || !!n.wants_contact;
const escalate = high_value || urgent || wants_contact;
return [{ json: { ...n, summary: p.summary || 'New referral submitted', suggested_owner_message: p.suggested_owner_message || '', high_value, urgent, wants_contact, escalate } }];

